 private Brush BrushFor(WowUiObject i){var close=i.TemplateName?.Contains("UIPanelCloseButton",StringComparison.OrdinalIgnoreCase)==true;var path=i.Type==WowObjectType.Texture||close||i.Type is WowObjectType.Button or WowObjectType.CheckButton?i.TexturePath:i.BackdropBackground;var normalized=string.IsNullOrWhiteSpace(path)?"":AssetResolver.Normalize(path);if(normalized.Contains("WHITE8X8",StringComparison.OrdinalIgnoreCase))return ColorBrush(i.Type==WowObjectType.Texture?i.VertexColor:i.BackdropColor);if(!string.IsNullOrWhiteSpace(path)&&_vm.ClientIndex is not null){var coords=i.TextureCoordinates;var crop=$"{coords[0]:0.######},{coords[1]:0.######},{coords[2]:0.######},{coords[3]:0.######}";var key=normalized+"|"+crop;if(_textureBrushes.TryGetValue(key,out var loaded))return loaded;StartTextureLoad(key,path,coords);if(_vm.Document.ReadOnlyClientPreview)return new SolidColorBrush(Color.FromArgb(24,0,0,0));}if(i.Type is WowObjectType.FontString)return Brushes.Transparent;if(close)return Brushes.Transparent;if(_vm.Document.ReadOnlyClientPreview&&i.Type is WowObjectType.Button or WowObjectType.CheckButton or WowObjectType.Texture)return Brushes.Transparent;if(i.Type is WowObjectType.Button or WowObjectType.CheckButton&&i.TemplateName?.Contains("UIPanel",StringComparison.OrdinalIgnoreCase)==true)return new LinearGradientBrush(Color.FromRgb(128,9,4),Color.FromRgb(52,2,1),90);if(!string.IsNullOrWhiteSpace(i.BackdropBackground))return ColorBrush(i.BackdropColor);return i.Type switch { WowObjectType.Button or WowObjectType.CheckButton => new SolidColorBrush(Color.FromRgb(72,18,14)), WowObjectType.EditBox => new SolidColorBrush(Color.FromRgb(12,12,14)), WowObjectType.StatusBar => new SolidColorBrush(Color.FromRgb(35,110,55)), WowObjectType.Texture => ColorBrush(i.VertexColor), _ => Brushes.Transparent };}
