 private async void StartTextureLoad(string key,string requested,double[] coords){if(!_textureLoads.Add(key)||_vm.ClientIndex is null)return;try{var resolved=new AssetResolver(_vm.ClientIndex.Files).Resolve(requested);var diskPath=resolved.File?.DiskPath;if(diskPath is null&&_profile is not null)diskPath=AssetResolver.ResolveFromInterfaceFolder(_profile.InterfaceRoot,requested);if(diskPath is null){if(!_vm.Document.Diagnostics.Any(x=>x.Category=="Missing texture"&&x.Message.Contains(requested,StringComparison.OrdinalIgnoreCase)))_vm.Document.Diagnostics.Add(new(DiagnosticSeverity.Warning,"Missing texture",$"{requested}; attempted: {string.Join(", ",resolved.AttemptedPaths)}"));return;}var texture=await _textureCache.GetOrDecodeAsync(diskPath,DecodeTextureAsync);var width=Math.Max(0.0001,coords[1]-coords[0]);var height=Math.Max(0.0001,coords[3]-coords[2]);var brush=new ImageBrush(WpfTextureFactory.Create(texture)){Stretch=Stretch.Fill,ViewboxUnits=BrushMappingMode.RelativeToBoundingBox,Viewbox=new Rect(coords[0],coords[2],width,height)};brush.Freeze();_textureBrushes[key]=brush;RenderPreview();}catch(Exception ex){_vm.Document.Diagnostics.Add(new(DiagnosticSeverity.Warning,"Texture decode",$"{requested}: {ex.Message}"));}finally{_textureLoads.Remove(key);}}
