 private async Task ReplayPreviewRequestAsync(AioRequestRegistration request){var tab=request.Handler.ToUpperInvariant() switch{"REQUESTTAB"=>request.Arguments.FirstOrDefault() as string,"REQUESTHOME"=>"home","REQUESTCHALLENGES"=>Convert.ToInt32(request.Arguments.FirstOrDefault()??1)==2?"weekly":"daily","REQUESTLOOT"=>"loot","REQUESTLFG"=>"lfg","REQUESTLEADERBOARD"=>"leaderboards",_=>null};if(string.IsNullOrWhiteSpace(tab))return;JsonObject payload;try{payload=JsonNode.Parse(string.IsNullOrWhiteSpace(AioPayloadJson.Text)?"{}":AioPayloadJson.Text) as JsonObject??new JsonObject();}catch{payload=new JsonObject();}payload["activeTab"]=tab;if(tab is "daily" or "weekly")payload["tabData"]=new JsonObject{{"title",tab=="daily"?"Daily Challenges":"Weekly Challenges"}};else payload["tabData"]=new JsonObject();AioPayloadJson.Text=payload.ToJsonString(new JsonSerializerOptions{WriteIndented=true});var handler=_vm.Document.AioHandlers.FirstOrDefault(x=>x.Module.Equals(request.Module,StringComparison.OrdinalIgnoreCase)&&x.Handler.Equals("ShowWindow",StringComparison.OrdinalIgnoreCase));if(handler is null)return;using var json=JsonDocument.Parse(AioPayloadJson.Text);await _vm.InvokeAioHandlerAsync(handler,null,json.RootElement.Clone());}
