 {
  var handle=(ResizeHandle)((Thumb)s).Tag;var i=handle.Item;var dx=e.HorizontalChange/_vm.UiScale;var dy=e.VerticalChange/_vm.UiScale;var oldWidth=i.Width;var oldHeight=i.Height;i.Width=Math.Max(1,i.Width+(handle.Left?-dx:dx));i.Height=Math.Max(1,i.Height+(handle.Top?-dy:dy));dx=handle.Left?oldWidth-i.Width:i.Width-oldWidth;dy=handle.Top?oldHeight-i.Height:i.Height-oldHeight;var point=i.Anchor.Point.ToUpperInvariant();var x=i.Anchor.X;var y=i.Anchor.Y;if(handle.Left)x+=point.Contains("LEFT")?dx:point.Contains("RIGHT")?0:dx/2;else x+=point.Contains("RIGHT")?dx:point.Contains("LEFT")?0:dx/2;if(handle.Top)y-=point.Contains("TOP")?dy:point.Contains("BOTTOM")?0:dy/2;else y-=point.Contains("BOTTOM")?dy:point.Contains("TOP")?0:dy/2;i.Anchor=i.Anchor with{X=x,Y=y};var border=PreviewCanvas.Children.OfType<Border>().FirstOrDefault(x=>ReferenceEquals(x.Tag,i));if(border is not null){var rect=new WowLayoutEngine().Resolve(i,_vm.Document);border.Width=Math.Max(1,rect.Width*_vm.UiScale);border.Height=Math.Max(1,rect.Height*_vm.UiScale);Canvas.SetLeft(border,rect.Left*_vm.UiScale);Canvas.SetTop(border,rect.Top*_vm.UiScale);foreach(var thumb in PreviewCanvas.Children.OfType<Thumb>().Where(x=>x.Tag is ResizeHandle h&&ReferenceEquals(h.Item,i))){var h=(ResizeHandle)thumb.Tag;Canvas.SetLeft(thumb,Canvas.GetLeft(border)+(h.Left?-7:border.Width-7));Canvas.SetTop(thumb,Canvas.GetTop(border)+(h.Top?-7:border.Height-7));}}ShowProperties();
