 private void NavigateToSource(WowUiObject item){var span=item.Sources.Values.OrderBy(x=>x.Line).FirstOrDefault();var offset=span?.ValueStart??-1;var length=span?.ValueLength??0;if(offset<0&&!string.IsNullOrWhiteSpace(item.Text)){var quoted="\""+item.Text+"\"";offset=_vm.Source.IndexOf(quoted,StringComparison.Ordinal);length=quoted.Length;}if(offset<0&&!item.Name.StartsWith("anonymous#",StringComparison.Ordinal)){offset=_vm.Source.IndexOf(item.Name,StringComparison.Ordinal);length=item.Name.Length;}if(offset<0)return;Editor.CaretOffset=offset;Editor.Select(offset,Math.Max(0,length));Editor.ScrollToLine(1+_vm.Source.Take(offset).Count(c=>c=='\n'));}
 private void ConfirmGeometry(WowUiObject item,double? width,double? height,double? x,double? y){var requested=new[]{("Width",width),("Height",height),("X",x),("Y",y)}.Where(v=>v.Item2.HasValue).ToList();var mapped=requested.Where(v=>item.Sources.ContainsKey(v.Item1)).ToList();if(mapped.Count!=requested.Count){if(_preferences.AutoAcceptDesignerChanges){_vm.SaveDesignerGeometry(item,width,height,x,y);return;}if(MessageBox.Show("This control is generated by shared Lua code, so Studio cannot safely identify one Lua literal to change.\n\nSave a STUDIO-ONLY preview override? WoW will not read this override and the Lua addon will remain unchanged.","Preview-only layout",MessageBoxButton.YesNo,MessageBoxImage.Warning)==MessageBoxResult.Yes)_vm.SaveDesignerGeometry(item,width,height,x,y);else RefreshAll();return;}if(_preferences.AutoAcceptDesignerChanges){_vm.PatchGeometry(item,width,height,x,y);return;}var summary=string.Join("\n",mapped.Select(v=>$"{v.Item1}: {item.Sources[v.Item1].OriginalText} → {v.Item2:0.###}"));if(MessageBox.Show($"Apply this change directly to the Lua file?\n\n{summary}\n\nThis change will affect WoW after the edited file is deployed. A .mwstudio.bak backup will be kept.","Confirm Lua change",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes){RefreshAll();return;}_vm.PatchGeometry(item,width,height,x,y);}
