 private void Resolution_Changed(object s,SelectionChangedEventArgs e){if(!IsLoaded||Resolution.SelectedItem is not ComboBoxItem c)return;var p=c.Content.ToString()!.Split('x');_vm.PreviewWidth=double.Parse(p[0]);_vm.PreviewHeight=double.Parse(p[1]);_vm.Reload();} private void Scale_Changed(object s,SelectionChangedEventArgs e){if(!IsLoaded||Scale.SelectedItem is not ComboBoxItem c)return;_vm.UiScale=double.Parse(c.Content.ToString()!,CultureInfo.InvariantCulture);_vm.Reload();}
 private void Background_Click(object s,RoutedEventArgs e){var d=new OpenFileDialog{Filter="Images|*.png;*.jpg;*.jpeg;*.bmp"};if(d.ShowDialog()==true){BackgroundImage.Source=new BitmapImage(new Uri(d.FileName));_vm.BackgroundPath=d.FileName;}}
 private async void SetInterfaceRoot_Click(object sender,RoutedEventArgs e){using var dialog=new System.Windows.Forms.FolderBrowserDialog{Description="Select the extracted TBC Interface directory",UseDescriptionForTitle=true,ShowNewFolderButton=false,SelectedPath=_profile?.InterfaceRoot??""};if(dialog.ShowDialog()!=System.Windows.Forms.DialogResult.OK)return;var selected=Path.GetFullPath(dialog.SelectedPath);if(!Directory.Exists(selected)){MessageBox.Show("The selected directory does not exist.");return;}var cache=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"MasterWoW.UIStudio","Cache");var parent=Directory.GetParent(selected)?.FullName;_profile=new TbcClientProfile("MasterWoW TBC 2.4.3","2.4.3.8606",selected,cache,parent);_settings.Save(_profile);ScanStatus.Text="Interface root configured. Scanning…";await RunScanAsync(ScanMode.Incremental);}
 private async void ScanInterface_Click(object sender,RoutedEventArgs e)=>await RunScanAsync(ScanMode.Incremental);
 private async void RebuildCache_Click(object sender,RoutedEventArgs e)=>await RunScanAsync(ScanMode.FullRebuild);
 private async Task RunScanAsync(ScanMode mode,bool showReport=true){if(_profile is null){SetInterfaceRoot_Click(this,new RoutedEventArgs());if(_profile is null)return;}_scanCancellation?.Cancel();_scanCancellation=new CancellationTokenSource();ScanProgress.Visibility=Visibility.Visible;ScanProgress.IsIndeterminate=false;ScanProgress.Minimum=0;ScanStatus.Text="Starting scan…";var progress=new Progress<ScanProgress>(p=>{ScanStatus.Text=$"{p.Phase}: {p.CurrentFile}";if(p.Total.HasValue){ScanProgress.Maximum=p.Total.Value;ScanProgress.Value=p.Processed;}else ScanProgress.IsIndeterminate=true;});try{var index=await new InterfaceScanner().ScanAsync(_profile,mode,progress,_scanCancellation.Token);_vm.SetClientIndex(index);ScanStatus.Text=$"Scan complete: {index.Files.Count:N0} files";if(showReport)new ScanReportWindow(index){Owner=this}.Show();}catch(OperationCanceledException){ScanStatus.Text="Scan canceled";}catch(Exception ex){MessageBox.Show(ex.Message,"TBC client scan failed",MessageBoxButton.OK,MessageBoxImage.Error);ScanStatus.Text="Scan failed";}finally{ScanProgress.Visibility=Visibility.Collapsed;}}
 private void AssetBrowser_Click(object sender,RoutedEventArgs e){if(_vm.ClientIndex is null){MessageBox.Show("Scan a TBC Interface root first.");return;}var window=new AssetBrowserWindow(_vm.ClientIndex){Owner=this};window.UseRequested+=(_,asset)=>{if(_vm.Selected is { } item)_vm.ApplyRuntimeTexture(item,asset.File.WowPath);};window.Show();}
 private void TemplateExplorer_Click(object sender,RoutedEventArgs e){if(_vm.ClientIndex is null){MessageBox.Show("Scan a TBC Interface root first.");return;}var window=new TemplateExplorerWindow(_vm.ClientIndex){Owner=this};window.PreviewRequested+=(_,template)=>_vm.PreviewTemplate(template.Name);window.Show();}
 private void ScanReport_Click(object sender,RoutedEventArgs e){if(_vm.ClientIndex is null){MessageBox.Show("Scan a TBC Interface root first.");return;}new ScanReportWindow(_vm.ClientIndex){Owner=this}.Show();}
 private async void InvokeAio_Click(object sender,RoutedEventArgs e)
 {
  if(AioHandlers.SelectedItem is not AioHandlerRegistration handler)return;
  var button=sender as Button;if(button is not null)button.IsEnabled=false;
  try{using var json=JsonDocument.Parse(string.IsNullOrWhiteSpace(AioPayloadJson.Text)?"{}":AioPayloadJson.Text);await _vm.InvokeAioHandlerAsync(handler,null,json.RootElement.Clone());}
  catch(Exception ex){_vm.Document.Diagnostics.Add(new(DiagnosticSeverity.Error,"AIO handler",ex.Message));RefreshAll();}
  finally{if(button is not null)button.IsEnabled=true;}
 }
 private void ApiExplorer_Click(object sender,RoutedEventArgs e)=>new ApiExplorerWindow{Owner=this}.Show();
